for l in (O/'PER_SOURCE_NOTES.tsv').read_text().splitlines()[1:]:
 i,role,findings=l.split('\t',2);notes[int(i)]=(role,findings)
assert len(rows)==len(notes)==46 and sum(r['size_bytes'] for r in rows)==339474
reviews=[]
for r in rows:
 i=r['index'];p=O/'sources'/r['sha256'];assert sha(p)==r['sha256'];n=len(p.read_text().splitlines());assert n==r['lines'];role,finding=notes[i]
 reviews.append({'review_id':f'S{i:02}','sha256':r['sha256'],'representative_path':r['representative_path'],'bytes':r['size_bytes'],'lines':n,'read_scope':{'first_line':1,'last_line':n,'full_static_inspection':True,'source_executed':False,'source_imported':False,'source_compiled':False,'source_AST_parsed':False},'role':role,'findings':finding,'source_snapshot':'sources/'+r['sha256'],'numbered_snapshot':f'line_numbered/{i:02}.txt','provenance':prov[i],'containing_library_archive_ids':r.get('containing_library_archive_ids',[]),'stored_result_boundary':'Historical only; fresh reviewer reconciliation in FRESH_REVIEWER_CHECKS.json does not rerun supplied programs.'})
