start=json.load(open(O/'REGISTRY_START_SNAPSHOT.json'));end=json.load(open(O/'REGISTRY_END_SNAPSHOT.json'));inv=json.load(open('code_coverage_audit_0228/CODE_COVERAGE_INVENTORY.json'))
