(O/'DEDUPLICATION.json').write_text(json.dumps({'assigned':46,'registry_start_count':start['current_full_static_reads'],'registry_end_count':end['current_full_static_reads'],'already_in_start':sorted(assigned&before),'already_in_end':sorted(assigned&after),'new_full_reads':len(assigned-before),'new_coverage_credit':len(assigned-after),'central_registry_modified':False,'frozen_inventory_sha256':sha(Path('code_coverage_audit_0228/CODE_COVERAGE_INVENTORY.json')),'frozen_rows_static_complete':len(frozen)},indent=2))
now=datetime.datetime.now(datetime.timezone.utc).isoformat();evidence_sha=sha(O/'SOURCE_REVIEWS.json')
coverage={'package':name,'completed_utc':now,'assigned_batches':['batch_03.json'],'assigned_batch_hashes':46,'fully_read_hashes_this_review':46,'new_full_read_hashes':len(assigned-before),'new_coverage_credit':len(assigned-after),'previously_covered_hashes':len(assigned&before),'total_source_bytes_read':339474,'total_source_lines_read':sum(r['lines'] for r in reviews),'all_assigned_new_source_reads_complete':True,'all_research_material_checks_finished':False,'dependency_closure_complete':False,'source_execution':'none','source_import_compilation_syntax_parse':'none','scope_note':'Complete first-to-last inert inspection of all 46 assigned exact hashes; archived evidence remains historical. No central registry changes.','rows':[{'review_id':r['review_id'],'sha256':r['sha256'],'representative_path':r['representative_path'],'batch':'batch_03.json','bytes':r['bytes'],'lines':r['lines'],'full_static_inspection':True,'static_inspection_complete':True,'full_source_read':True,'line_ranges':[[1,r['lines']]],'source_executed_in_review':False,'evidence_file':'SOURCE_REVIEWS.json','evidence_sha256':evidence_sha,'snapshot':r['source_snapshot'],'new_coverage_credit':r['sha256'] not in after} for r in reviews]}
(O/'COVERAGE.json').write_text(json.dumps(coverage,indent=2));(O/'ASSIGNMENT.json').write_text(json.dumps({'package':name,'source_queue':'remaining_source_queue_0502/batch_03.json','source_queue_sha256':sha(Path('remaining_source_queue_0502/batch_03.json')),'assigned_hashes':46,'assigned_bytes':339474,'source_execution':'none','central_registry_modified':False},indent=2))
files=sorted(p for p in O.rglob('*') if p.is_file() and p.name not in ('SHA256SUMS.txt','SEAL.json'))
(O/'SHA256SUMS.txt').write_text(''.join(f'{sha(p)}  {p.relative_to(O)}\n' for p in files));assert all(sha(O/line[66:])==line[:64] for line in (O/'SHA256SUMS.txt').read_text().splitlines())
seal={'package':name,'sealed_utc':now,'file_count':len(files),'sealed_bytes':sum(p.stat().st_size for p in files),'sha256sums_sha256':sha(O/'SHA256SUMS.txt'),'coverage_sha256':sha(O/'COVERAGE.json'),'source_reviews_sha256':evidence_sha,'assigned_sources':46,'source_bytes':339474,'source_lines':coverage['total_source_lines_read'],'new_coverage_credit':coverage['new_coverage_credit'],'uploaded_source_execution':'none','uploaded_source_import_compile_AST':'none','central_registry_modified':False,'fresh_reviewer_checks':31,'all_package_digest_checks_passed':True}
